import sys


def main():
    flags = set()
    filename = None

    args = sys.argv[1:]
    i = 0
    while i < len(args):
        arg = args[i]
        if arg.startswith("-"):
            for ch in arg[1:]:
                flags.add(ch)
            i += 1
        else:
            filename = arg
            i += 1

    if not flags:
        flags = {"l", "w", "c"}

    if filename is None or filename == "-":
        data = sys.stdin.buffer.read()
    else:
        with open(filename, "rb") as f:
            data = f.read()

    text = data.decode("utf-8", errors="surrogateescape")

    lines = text.count("\n")
    # A final line with no trailing newline still counts as a line.
    if text and not text.endswith("\n"):
        lines += 1

    words = text.split()
    word_count = len(words)

    char_count = len(data)

    order = ["l", "w", "c"]
    results = []
    for flag in order:
        if flag in flags:
            if flag == "l":
                results.append(str(lines))
            elif flag == "w":
                results.append(str(word_count))
            elif flag == "c":
                results.append(str(char_count))

    print(" ".join(results))


if __name__ == "__main__":
    main()
